def _find_component(root, comp_type, check_fn=None):
    """Recursively search for a component of given type in the layout tree."""
    if isinstance(root, comp_type):
        if check_fn is None or check_fn(root):
            return root
    if hasattr(root, 'children'):
        if isinstance(root.children, list):
            for child in root.children:
                result = _find_component(child, comp_type, check_fn)
                if result is not None:
                    return result
        elif root.children is not None:
            return _find_component(root.children, comp_type, check_fn)
    if isinstance(root, list):
